@using sv_573a9e9723fb4a83a5651a3511d2a2fa.Services
@inject ISettingsService SettingsService

<div class="settings-section">
    <h3>Security Settings</h3>

    @if (_loading)
    {
        <p>Loading...</p>
    }
    else
    {
        <ChangePasswordPanel OnPasswordChanged="HandlePasswordChangedAsync" />

        <div class="two-factor-section mt-4">
            <h4>Two-Factor Authentication</h4>
            <div class="toggle-label">
                <span>
                    @if (_twoFactorEnabled)
                    {
                        <span class="badge bg-success me-2">Enabled</span>
                    }
                    else
                    {
                        <span class="badge bg-warning me-2">Disabled</span>
                    }
                    Two-Factor Authentication
                </span>
                <label class="switch">
                    <input type="checkbox" @bind="_twoFactorEnabled" />
                    <span class="slider"></span>
                </label>
            </div>
            @if (_lastPasswordChange.HasValue)
            {
                <p class="text-muted mt-2">Last password change: @_lastPasswordChange.Value.ToString("MMM dd, yyyy")</p>
            }
        </div>

        <ActiveSessionsTable Sessions="_sessions"
                             CurrentSessionId="sess-1"
                             OnRevoke="RevokeSessionAsync" />

        @if (_showSuccess)
        {
            <div class="alert alert-success mt-3 fade-in">@_successMessage</div>
        }
    }
</div>

@code {
    private bool _twoFactorEnabled;
    private DateTime? _lastPasswordChange;
    private List<ActiveSession> _sessions = [];
    private bool _loading = true;
    private bool _showSuccess;
    private string _successMessage = "";

    protected override async Task OnInitializedAsync()
    {
        var settings = await SettingsService.GetSecuritySettingsAsync();
        _twoFactorEnabled = settings.TwoFactorEnabled;
        _lastPasswordChange = settings.LastPasswordChange;
        _sessions = [.. settings.Sessions];
        _loading = false;
    }

    private async Task HandlePasswordChangedAsync()
    {
        await SettingsService.ChangePasswordAsync("", "");
        _lastPasswordChange = DateTime.UtcNow;
        ShowSuccess("Password updated successfully!");
    }

    private async Task RevokeSessionAsync(string sessionId)
    {
        await SettingsService.RevokeSessionAsync(sessionId);
        _sessions.RemoveAll(s => s.Id == sessionId);
        ShowSuccess("Session revoked successfully!");
    }

    private void ShowSuccess(string message)
    {
        _successMessage = message;
        _showSuccess = true;
        _ = HideSuccessAfterDelay();
    }

    private async Task HideSuccessAfterDelay()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}

