toolArgs.file_text:
@using sv_573a9e9723fb4a83a5651a3511d2a2fa.Services
@inject ISettingsService SettingsService

<div class="settings-section">
    <h3>Appearance</h3>

    @if (_loading)
    {
        <p>Loading...</p>
    }
    else
    {
        <div class="appearance-form">
            <div class="form-group">
                <label><strong>Theme</strong></label>
                <div class="radio-group">
                    @foreach (var theme in new[] { "Light", "Dark", "System" })
                    {
                        <label class="radio-item">
                            <input type="radio" name="theme" value="@theme"
                                   checked="@(_theme == theme)"
                                   @onchange="() => _theme = theme" />
                            <span>@theme</span>
                        </label>
                    }
                </div>
            </div>

            <div class="form-group">
                <label><strong>Font Size</strong></label>
                <div class="radio-group">
                    @foreach (var size in new[] { "Small", "Medium", "Large" })
                    {
                        <label class="radio-item">
                            <input type="radio" name="fontSize" value="@size"
                                   checked="@(_fontSize == size)"
                                   @onchange="() => _fontSize = size" />
                            <span>@size</span>
                        </label>
                    }
                </div>
            </div>

            <div class="form-group">
                <label for="language"><strong>Language</strong></label>
                <select id="language" class="form-control" @bind="_language">
                    @foreach (var lang in _languages)
                    {
                        <option value="@lang">@lang</option>
                    }
                </select>
            </div>

            <div class="form-group">
                <label class="toggle-label">
                    <span><strong>Compact Mode</strong></span>
                    <label class="switch">
                        <input type="checkbox" @bind="_compactMode" />
                        <span class="slider"></span>
                    </label>
                </label>
            </div>

            <div class="preview-area">
                <h5>Live Preview</h5>
                <div class="preview-box @GetPreviewClasses()">
                    <div class="preview-header">Sample Header</div>
                    <p class="preview-text">This is how your content will look with the selected settings.</p>
                    <div class="preview-actions">
                        <button class="btn btn-sm btn-primary">Primary Action</button>
                        <button class="btn btn-sm btn-outline-secondary">Secondary</button>
                    </div>
                </div>
            </div>

            <div class="form-actions">
                <button class="btn btn-primary" @onclick="SaveAsync">Save</button>
            </div>

            @if (_showSuccess)
            {
                <div class="alert alert-success mt-3 fade-in">Appearance settings saved!</div>
            }
        </div>
    }
</div>

@code {
    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;
    private bool _loading = true;
    private bool _showSuccess;

    private static readonly string[] _languages = ["English", "Spanish", "French", "German", "Japanese", "Chinese", "Portuguese"];

    protected override async Task OnInitializedAsync()
    {
        var settings = await SettingsService.GetAppearanceAsync();
        _theme = settings.Theme;
        _fontSize = settings.FontSize;
        _language = settings.Language;
        _compactMode = settings.CompactMode;
        _loading = false;
    }

    private string GetPreviewClasses()
    {
        var classes = new List<string>();
        classes.Add($"preview-theme-{_theme.ToLowerInvariant()}");
        classes.Add($"preview-font-{_fontSize.ToLowerInvariant()}");
        if (_compactMode) classes.Add("preview-compact");
        return string.Join(' ', classes);
    }

    private async Task SaveAsync()
    {
        var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        _showSuccess = true;
        _ = HideSuccessAfterDelay();
    }

    private async Task HideSuccessAfterDelay()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}

